[CustomEditor(typeof(PuzzleRegistry))]
public class PuzzleRegistryEditor : Editor
{
    public override void OnInspectorGUI()
    {
        DrawDefaultInspector();

        PuzzleRegistry registry = (PuzzleRegistry)target;

        EditorGUILayout.Space();

        if (GUILayout.Button("Gather All Puzzles In Project"))
        {
            GatherAllPuzzles(registry);
        }

        if (GUILayout.Button("Assign Missing Ids"))
        {
            AssignMissingIds();
        }

        if (GUILayout.Button("Validate"))
        {
            Validate(registry);
        }
    }


    // MARK: actions


    internal static void GatherAllPuzzles(PuzzleRegistry registry)
    {
        if (registry == null)
        {
            Debug.LogError("PuzzleRegistryEditor: no registry to gather into, so nothing was gathered");
            return;
        }

        List<Puzzle> found = FindAllPuzzles();

        List<Puzzle> ordered = OrderPuzzles(registry, found);

        Undo.RecordObject(registry, "Gather Puzzles");

        SerializedObject serialized = new SerializedObject(registry);
        SerializedProperty list = serialized.FindProperty("puzzles");

        list.arraySize = ordered.Count;
        for (int i = 0; i < ordered.Count; i++)
        {
            list.GetArrayElementAtIndex(i).objectReferenceValue = ordered[i];
        }

        // startingPuzzles deliberately untouched: gathering must not silently change what a new world
        // begins with
        serialized.ApplyModifiedProperties();

        registry.Rebuild();

        Debug.Log($"PuzzleRegistry: gathered {ordered.Count} puzzles", registry);
    }


    internal static void AssignMissingIds()
    {
        List<Puzzle> all = FindAllPuzzles();
        all.Sort((a, b) => string.CompareOrdinal(a.name, b.name));

        HashSet<string> taken = new HashSet<string>();
        List<Puzzle> missing = new List<Puzzle>();

        foreach (Puzzle puzzle in all)
        {
            if (string.IsNullOrEmpty(puzzle.Id)) missing.Add(puzzle);
            else taken.Add(puzzle.Id);
        }

        foreach (Puzzle puzzle in missing)
        {
            string id = MakeUnique(Slug(puzzle.name), taken);

            // Puzzle.Id is a read-only property, so the private backing field is the only way in
            Undo.RecordObject(puzzle, "Assign Puzzle Id");

            SerializedObject serialized = new SerializedObject(puzzle);
            serialized.FindProperty("id").stringValue = id;
            serialized.ApplyModifiedProperties();

            EditorUtility.SetDirty(puzzle);

            taken.Add(id);
            Debug.Log($"PuzzleRegistry: assigned id '{id}' to '{puzzle.name}'", puzzle);
        }

        if (missing.Count == 0) Debug.Log("PuzzleRegistry: no missing ids");
    }


    internal static int Validate(PuzzleRegistry registry)
    {
        if (registry == null)
        {
            Debug.LogError("PuzzleRegistryEditor: no registry to validate, so nothing was validated");
            return 1;
        }

        SerializedObject serialized = new SerializedObject(registry);
        SerializedProperty list = serialized.FindProperty("puzzles");
        SerializedProperty starting = serialized.FindProperty("startingPuzzles");

        Dictionary<string, Puzzle> byId = new Dictionary<string, Puzzle>();
        int problems = 0;

        problems += ValidateEntries(registry, list, byId);
        problems += ValidateIngredients(byId);
        problems += ValidateUnlocks(registry, byId);
        problems += ValidateStarting(registry, starting, byId);

        // A puzzle that exists in the project but was forgotten here can never be saved, because the
        // registry is the only thing that resolves an id back to an asset
        HashSet<Puzzle> registered = new HashSet<Puzzle>(byId.Values);

        foreach (Puzzle puzzle in FindAllPuzzles())
        {
            if (registered.Contains(puzzle)) continue;

            Debug.LogError($"PuzzleRegistry: '{puzzle.name}' is a Puzzle in the project but is not in " +
                $"this registry", puzzle);
            problems++;
        }

        problems += ValidateReachability(registry, byId);

        if (problems == 0)
        {
            Debug.Log($"PuzzleRegistry: {byId.Count} puzzles, all ids present and unique, " +
                $"all reachable from {starting.arraySize} starting puzzle(s)", registry);
        }
        else
        {
            Debug.LogError($"PuzzleRegistry: {problems} problem(s) found", registry);
        }

        return problems;
    }


    // MARK: ordering


    // Orders the gathered puzzles into the order the player meets them: the starting puzzles, then
    // what they unlock, and so on, each depth A->Z. Puzzles the walk never reaches sort last A->Z
    // with a warning naming each one.
    private static List<Puzzle> OrderPuzzles(PuzzleRegistry registry, List<Puzzle> found)
    {
        PuzzleTreeWalker.Result walk = PuzzleTreeWalker.Walk(registry.StartingPuzzles);

        // flatten the levels into one meet-ordered list
        List<Puzzle> reached = new List<Puzzle>();

        for (int depth = 0; depth < walk.Levels.Count; depth++)
        {
            reached.AddRange(walk.Levels[depth]);
        }

        // puzzles in the project that no starting puzzle reaches go last
        List<Puzzle> unreached = new List<Puzzle>();

        for (int i = 0; i < found.Count; i++)
        {
            if (walk.Reached.Contains(found[i])) continue;

            unreached.Add(found[i]);
        }

        unreached.Sort((a, b) => string.CompareOrdinal(a.name, b.name));

        foreach (Puzzle puzzle in unreached)
        {
            Debug.LogWarning($"PuzzleRegistry: '{puzzle.name}' is not reachable from any starting puzzle, so it sorts last", puzzle);
        }

        // assemble: reached first in meet order, then unreached A->Z. The walk follows unlocks that
        // point outside the registry, so only registered puzzles are written.
        List<Puzzle> ordered = new List<Puzzle>(found.Count);
        HashSet<Puzzle> registered = new HashSet<Puzzle>(found);

        for (int i = 0; i < reached.Count; i++)
        {
            if (registered.Contains(reached[i])) ordered.Add(reached[i]);
        }

        for (int i = 0; i < unreached.Count; i++)
        {
            ordered.Add(unreached[i]);
        }

        return ordered;
    }


    // MARK: validation passes


    private static int ValidateEntries(PuzzleRegistry registry, SerializedProperty list, Dictionary<string, Puzzle> byId)
    {
        int problems = 0;

        for (int i = 0; i < list.arraySize; i++)
        {
            Puzzle puzzle = list.GetArrayElementAtIndex(i).objectReferenceValue as Puzzle;

            if (puzzle == null)
            {
                Debug.LogError($"PuzzleRegistry: entry {i} is empty", registry);
                problems++;
                continue;
            }

            if (string.IsNullOrEmpty(puzzle.Id))
            {
                Debug.LogError($"PuzzleRegistry: '{puzzle.name}' has no Id", puzzle);
                problems++;
                continue;
            }

            if (byId.TryGetValue(puzzle.Id, out Puzzle other))
            {
                Debug.LogError($"PuzzleRegistry: duplicate Id '{puzzle.Id}' on '{puzzle.name}' and " +
                    $"'{other.name}'", puzzle);
                problems++;
                continue;
            }

            byId.Add(puzzle.Id, puzzle);
        }

        return problems;
    }


    private static int ValidateIngredients(Dictionary<string, Puzzle> byId)
    {
        int problems = 0;

        foreach (KeyValuePair<string, Puzzle> pair in byId)
        {
            Puzzle puzzle = pair.Value;

            SerializedObject serialized = new SerializedObject(puzzle);
            SerializedProperty ingredients = serialized.FindProperty("ingredients");

            if (ingredients.arraySize == 0)
            {
                // Not fatal, but such a puzzle can never be soft locked and hands the player nothing
                Debug.LogWarning($"PuzzleRegistry: '{puzzle.name}' has no ingredients, so it grants " +
                    $"nothing and can never be flagged as soft locked", puzzle);
            }

            HashSet<GameItem> seen = new HashSet<GameItem>();

            for (int i = 0; i < ingredients.arraySize; i++)
            {
                SerializedProperty element = ingredients.GetArrayElementAtIndex(i);
                GameItem item = element.FindPropertyRelative("item").objectReferenceValue as GameItem;
                int count = element.FindPropertyRelative("count").intValue;

                if (item == null)
                {
                    Debug.LogError($"PuzzleRegistry: '{puzzle.name}' ingredient {i} is empty", puzzle);
                    problems++;
                    continue;
                }

                if (count <= 0)
                {
                    Debug.LogError($"PuzzleRegistry: '{puzzle.name}' lists {count}x '{item.name}', " +
                        $"which grants nothing", puzzle);
                    problems++;
                    continue;
                }

                if (!seen.Add(item))
                {
                    // Legal, RequiredCount sums the entries, but it is almost always a typo
                    Debug.LogWarning($"PuzzleRegistry: '{puzzle.name}' lists '{item.name}' more than " +
                        $"once; the counts are summed", puzzle);
                }
            }
        }

        return problems;
    }


    private static int ValidateUnlocks(PuzzleRegistry registry, Dictionary<string, Puzzle> byId)
    {
        int problems = 0;

        foreach (KeyValuePair<string, Puzzle> pair in byId)
        {
            Puzzle puzzle = pair.Value;

            SerializedObject serialized = new SerializedObject(puzzle);
            SerializedProperty unlocks = serialized.FindProperty("unlocks");

            for (int i = 0; i < unlocks.arraySize; i++)
            {
                Puzzle unlocked = unlocks.GetArrayElementAtIndex(i).objectReferenceValue as Puzzle;

                if (unlocked == null)
                {
                    Debug.LogError($"PuzzleRegistry: '{puzzle.name}' unlock {i} is empty", puzzle);
                    problems++;
                    continue;
                }

                if (unlocked == puzzle)
                {
                    Debug.LogError($"PuzzleRegistry: '{puzzle.name}' unlocks itself", puzzle);
                    problems++;
                    continue;
                }

                if (!byId.ContainsValue(unlocked))
                {
                    Debug.LogError($"PuzzleRegistry: '{puzzle.name}' unlocks '{unlocked.name}', which is " +
                        $"not in this registry, so it could never be resolved from a save", puzzle);
                    problems++;
                }
            }
        }

        return problems;
    }


    private static int ValidateStarting(PuzzleRegistry registry, SerializedProperty starting, Dictionary<string, Puzzle> byId)
    {
        int problems = 0;

        if (starting.arraySize == 0)
        {
            Debug.LogError($"PuzzleRegistry: '{registry.name}' has no starting puzzles, so a new world " +
                $"begins with nothing to do", registry);
            return 1;
        }

        HashSet<Puzzle> seen = new HashSet<Puzzle>();

        for (int i = 0; i < starting.arraySize; i++)
        {
            Puzzle puzzle = starting.GetArrayElementAtIndex(i).objectReferenceValue as Puzzle;

            if (puzzle == null)
            {
                Debug.LogError($"PuzzleRegistry: starting puzzle {i} is empty", registry);
                problems++;
                continue;
            }

            if (!seen.Add(puzzle))
            {
                Debug.LogError($"PuzzleRegistry: starting puzzle {i} repeats '{puzzle.name}'", registry);
                problems++;
                continue;
            }

            if (!byId.ContainsValue(puzzle))
            {
                Debug.LogError($"PuzzleRegistry: starting puzzle '{puzzle.name}' is not in the puzzles " +
                    $"list, so it can never be resolved from a save", registry);
                problems++;
            }
        }

        return problems;
    }


    // Every registered puzzle has to be reachable from a starting puzzle, or nothing can ever unlock it
    private static int ValidateReachability(PuzzleRegistry registry, Dictionary<string, Puzzle> byId)
    {
        int problems = 0;

        // Unlocks that point outside the registry are reported by ValidateUnlocks; the walk still
        // follows them here so a half-finished registry does not also report every child as unreachable.
        PuzzleTreeWalker.Result walk = PuzzleTreeWalker.Walk(registry.StartingPuzzles);

        foreach (KeyValuePair<string, Puzzle> pair in byId)
        {
            if (walk.Reached.Contains(pair.Value)) continue;

            Debug.LogError($"PuzzleRegistry: '{pair.Value.name}' can never be unlocked - no starting " +
                $"puzzle reaches it", pair.Value);
            problems++;
        }

        return problems;
    }


    // MARK: helpers


    private static List<Puzzle> FindAllPuzzles()
    {
        List<Puzzle> found = new List<Puzzle>();

        foreach (string guid in AssetDatabase.FindAssets("t:Puzzle"))
        {
            Puzzle puzzle = AssetDatabase.LoadAssetAtPath<Puzzle>(AssetDatabase.GUIDToAssetPath(guid));
            if (puzzle != null) found.Add(puzzle);
        }

        return found;
    }


    // "Spring Blooms" becomes "spring_blooms"
    private static string Slug(string name)
    {
        StringBuilder builder = new StringBuilder(name.Length);

        for (int i = 0; i < name.Length; i++)
        {
            char c = char.ToLowerInvariant(name[i]);

            if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
            {
                builder.Append(c);
            }
            // runs of separators collapse to a single underscore, and never lead with one
            else if (builder.Length > 0 && builder[builder.Length - 1] != '_')
            {
                builder.Append('_');
            }
        }

        while (builder.Length > 0 && builder[builder.Length - 1] == '_')
        {
            builder.Length--;
        }

        return builder.Length > 0 ? builder.ToString() : "puzzle";
    }


    private static string MakeUnique(string baseId, HashSet<string> taken)
    {
        if (!taken.Contains(baseId)) return baseId;

        for (int suffix = 2; ; suffix++)
        {
            string candidate = baseId + "_" + suffix;
            if (!taken.Contains(candidate)) return candidate;
        }
    }
}
